import json
from fractions import Fraction as F

def trim(p):
    p = list(map(F, p))
    while len(p) > 1 and p[-1] == 0:
        p.pop()
    return p

def add(p, q):
    r = [F(0)] * max(len(p), len(q))
    for i, x in enumerate(p):
        r[i] += x
    for i, x in enumerate(q):
        r[i] += x
    return trim(r)

def mul(p, q):
    r = [F(0)] * (len(p) + len(q) - 1)
    for i, x in enumerate(p):
        for j, y in enumerate(q):
            r[i + j] += x * y
    return trim(r)

def divmod_poly(p, q):
    p, q = trim(p), trim(q)
    if q == [0]:
        raise ZeroDivisionError
    result = [F(0)] * max(1, len(p) - len(q) + 1)
    while p != [0] and len(p) >= len(q):
        k = len(p) - len(q)
        c = p[-1] / q[-1]
        result[k] += c
        p = add(p, [F(0)] * k + [-c * x for x in q])
    return trim(result), p

def gcd_poly(p, q):
    while q != [0]:
        _, remainder = divmod_poly(p, q)
        p, q = q, remainder
    return [x / p[-1] for x in p]

def polynomial_text(p):
    terms = []
    for degree in range(len(p) - 1, -1, -1):
        c = p[degree]
        if not c:
            continue
        magnitude = abs(c)
        variable = "" if degree == 0 else ("a" if degree == 1 else f"a^{degree}")
        coefficient = "" if variable and magnitude == 1 else str(magnitude)
        term = coefficient + variable
        if not terms:
            terms.append(("-" if c < 0 else "") + term)
        else:
            terms.append((" - " if c < 0 else " + ") + term)
    return "".join(terms) or "0"

# Original expression: (P/Q) / (R/S) - T/U.
P, Q = [-9, 0, 1], [9, 6, 1]
R, S = [-3, 1], [0, 3, 1]
T, U = [0, 1, -1], [-1, 1]

numerator = add(mul(mul(P, S), U),
                [-x for x in mul(mul(T, Q), R)])
denominator = mul(mul(Q, R), U)
g = gcd_poly(numerator, denominator)
n, nr = divmod_poly(numerator, g)
d, dr = divmod_poly(denominator, g)

if nr != [0] or dr != [0]:
    print("UNSUPPORTED")
else:
    scale = d[-1]
    n, d = [x / scale for x in n], [x / scale for x in d]
    simplified = polynomial_text(n)
    if d != [1]:
        simplified = f"({simplified})/({polynomial_text(d)})"

    candidates = {}
    valid = []
    for a in (0, 1, 2, 3):
        reasons = []
        if a * a + 6 * a + 9 == 0:
            reasons.append("first denominator is zero")
        if a * a + 3 * a == 0:
            reasons.append("divisor denominator is zero")
        if a - 3 == 0:
            reasons.append("divisor is zero")
        if a - 1 == 0:
            reasons.append("last denominator is zero")
        if reasons:
            candidates[str(a)] = {"valid": False, "reasons": reasons}
        else:
            value = (
                F(a * a - 9, a * a + 6 * a + 9)
                / F(a - 3, a * a + 3 * a)
                - F(a - a * a, a - 1)
            )
            candidates[str(a)] = {"valid": True, "value": str(value)}
            valid.append((a, value))

    if not valid:
        print("UNSUPPORTED")
    else:
        a, value = valid[0]
        print(json.dumps({
            "final_answer": f"Simplified expression: {simplified}. "
                            f"Choose a = {a}; the value is {value}.",
            "evidence": {
                "reduced_numerator_coefficients": [str(x) for x in n],
                "reduced_denominator_coefficients": [str(x) for x in d],
                "candidate_checks": candidates
            }
        }, separators=(",", ":")))
